import { Request, Response, Router } from 'express';
import { AssignTaskUseCase } from '../../../application/use-cases/AssignTaskUseCase';
import { CompleteTaskUseCase } from '../../../application/use-cases/CompleteTaskUseCase';
import { readBody, requiredString } from '../RequestParsing';

export class TaskController {
  constructor(
    private readonly assignTask: AssignTaskUseCase,
    private readonly completeTask: CompleteTaskUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.put('/tasks/:taskId/assignee', (req, res) => this.assign(req, res));
    router.post('/tasks/:taskId/complete', (req, res) => this.complete(req, res));
    return router;
  }

  async assign(req: Request, res: Response): Promise<void> {
    const body = readBody(req.body);
    const task = await this.assignTask.execute({
      taskId: String(req.params.taskId),
      userId: requiredString(body, 'userId'),
    });
    res.json(task);
  }

  async complete(req: Request, res: Response): Promise<void> {
    const task = await this.completeTask.execute(String(req.params.taskId));
    res.json(task);
  }
}

